=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none
// skid_buffer: one-beat register slice for a valid/ready stream.
// Two registers (output + skid); every output is a flop or the inverse of one.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat moves on this edge.
    wire s_fire = s_valid && s_ready;

    // Inverse of a flop: high while at most one beat is held.
    assign s_ready = !skid_valid;

    // Control registers, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            // Skid beat (if any) moves to the output; otherwise the input does.
            m_valid    <= skid_valid || s_valid;
            skid_valid <= 1'b0;
        end else if (s_fire) begin
            // Output stalled and a beat was accepted: catch it in the skid register.
            skid_valid <= 1'b1;
        end
    end

    // Output data register: loads only when the output register may load.
    always @(posedge clk) begin
        if (m_free) begin
            if (skid_valid)
                m_data <= skid_data;
            else
                m_data <= s_data;
        end
    end

    // Skid data register: loads only when a beat is caught.
    always @(posedge clk) begin
        if (!m_free && s_fire)
            skid_data <= s_data;
    end

`ifdef FORMAL
    // Design-intent properties (not proven in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume (!rst_n);

    // The skid register is only full while the output register is full.
    always @(*) if (f_past_valid && skid_valid) assert (m_valid);

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert (!m_valid);
            assert (!skid_valid);
        end
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
            // Hold: a stalled beat stays offered, unchanged.
            assert (m_valid);
            assert (m_data == $past(m_data));
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
