`timescale 1ns/1ps
`default_nettype none
// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;
    wire       s_ready;
    wire       m_valid;
    wire [7:0] m_data;
    wire       s_data1;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    assign s_data1 = s_data[0];

    skid_buffer #(.WIDTH(8)) u_w8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready), .s_data(s_data),
        .m_valid(m_valid), .m_ready(m_ready), .m_data(m_data)
    );

    skid_buffer #(.WIDTH(1)) u_w1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data1),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    initial clk = 1'b0;
    always #10 clk = ~clk;

    // Reference model: queue of up to two beats.
    reg [7:0] q0;
    reg [7:0] q1;
    integer   count;
    integer   n_in;
    integer   n_out;
    integer   n_drop;
    integer   passed;
    integer   failed;
    integer   i;
    integer   k;
    integer   seed;
    reg [31:0] r;
    reg        rnd_mr;
    reg        seen_reset;
    reg        last_up;
    reg        last_dn;
    reg        dut_up;
    reg        dut_dn;
    reg [7:0]  out_beat;
    reg        prev_hold;
    reg [7:0]  prev_mdata;
    reg        prev_mdata1;
    reg        finished;
    reg [8*64-1:0] nonce;

    task check;
        input            ok;
        input [8*64-1:0] what;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL t=%0t: %0s", $time, what);
            end
        end
    endtask

    task finish_run;
        begin
            if (!finished) begin
                finished = 1'b1;
                if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
                    nonce = "unset";
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task model_update;
        input       sv_i;
        input [7:0] sd_i;
        input       mr_i;
        begin
            last_up = 1'b0;
            last_dn = 1'b0;
            if (!rst_n) begin
                n_drop     = n_drop + count;
                count      = 0;
                seen_reset = 1'b1;
            end else begin
                last_up = sv_i && (count < 2);
                last_dn = mr_i && (count > 0);
                if (last_dn) begin
                    q0    = q1;
                    count = count - 1;
                    n_out = n_out + 1;
                end
                if (last_up) begin
                    if (count == 0) q0 = sd_i;
                    else            q1 = sd_i;
                    count = count + 1;
                    n_in  = n_in + 1;
                end
            end
        end
    endtask

    task check_outputs;
        begin
            if (seen_reset) begin
                check(m_valid  === (count > 0), "w8 m_valid matches beats held");
                check(s_ready  === (count < 2), "w8 s_ready matches beats held");
                check(m_valid1 === (count > 0), "w1 m_valid matches beats held");
                check(s_ready1 === (count < 2), "w1 s_ready matches beats held");
                if (count > 0) begin
                    check(m_data === q0,          "w8 m_data is the oldest beat");
                    check(m_data1[0] === q0[0],   "w1 m_data is the oldest beat");
                end
                if (prev_hold) begin
                    check(m_valid === 1'b1 && m_data === prev_mdata,
                          "w8 stalled beat holds with same data");
                    check(m_valid1 === 1'b1 && m_data1[0] === prev_mdata1,
                          "w1 stalled beat holds with same data");
                end
            end
        end
    endtask

    task outputs_same;
        input            r8;
        input            v8;
        input [7:0]      d8;
        input            r1;
        input            v1;
        input            d1;
        input [8*64-1:0] what;
        begin
            if (seen_reset) begin
                check(s_ready === r8 && s_ready1 === r1,      what);
                check(m_valid === v8 && m_valid1 === v1,      what);
                check(m_data === d8 && m_data1[0] === d1,     what);
            end
        end
    endtask

    // Flip inputs inside the cycle; no output may move.
    task glitch_check;
        reg       g_r8;
        reg       g_v8;
        reg [7:0] g_d8;
        reg       g_r1;
        reg       g_v1;
        reg       g_d1;
        begin
            g_r8 = s_ready;  g_v8 = m_valid;  g_d8 = m_data;
            g_r1 = s_ready1; g_v1 = m_valid1; g_d1 = m_data1[0];
            m_ready = ~m_ready;
            #1;
            outputs_same(g_r8, g_v8, g_d8, g_r1, g_v1, g_d1, "outputs ignore m_ready in-cycle");
            s_valid = ~s_valid;
            #1;
            outputs_same(g_r8, g_v8, g_d8, g_r1, g_v1, g_d1, "outputs ignore s_valid in-cycle");
            s_data = ~s_data;
            #1;
            outputs_same(g_r8, g_v8, g_d8, g_r1, g_v1, g_d1, "outputs ignore s_data in-cycle");
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            outputs_same(g_r8, g_v8, g_d8, g_r1, g_v1, g_d1, "outputs stable after inputs restored");
        end
    endtask

    // One clock cycle: called just after a falling edge, returns after the next one.
    task cycle;
        input       sv_i;
        input [7:0] sd_i;
        input       mr_i;
        begin
            s_valid = sv_i;
            s_data  = sd_i;
            m_ready = mr_i;
            #1;
            glitch_check;
            dut_up      = sv_i && (s_ready === 1'b1);
            dut_dn      = mr_i && (m_valid === 1'b1);
            out_beat    = m_data;
            prev_hold   = seen_reset && rst_n && (m_valid === 1'b1) && !mr_i;
            prev_mdata  = m_data;
            prev_mdata1 = m_data1[0];
            @(posedge clk);
            model_update(sv_i, sd_i, mr_i);
            @(negedge clk);
            check_outputs;
        end
    endtask

    initial begin
        passed = 0; failed = 0;
        count = 0; n_in = 0; n_out = 0; n_drop = 0;
        q0 = 8'h00; q1 = 8'h00;
        seed = 1;
        r = 32'd0; rnd_mr = 1'b0;
        seen_reset = 1'b0; last_up = 1'b0; last_dn = 1'b0;
        dut_up = 1'b0; dut_dn = 1'b0; out_beat = 8'h00;
        prev_hold = 1'b0; prev_mdata = 8'h00; prev_mdata1 = 1'b0;
        finished = 1'b0;
        nonce = 0;
        rst_n = 1'b0; s_valid = 1'b0; s_data = 8'h00; m_ready = 1'b0;

        @(negedge clk);

        // ---- Reset values (traffic offered during reset) ----
        cycle(1'b1, 8'h11, 1'b0);
        cycle(1'b1, 8'h22, 1'b1);
        check(m_valid === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low");
        check(s_ready === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high");
        rst_n = 1'b1;
        cycle(1'b0, 8'h00, 1'b0);
        check(m_valid === 1'b0 && s_ready === 1'b1, "idle after reset stays empty");

        // ---- One-cycle latency ----
        s_valid = 1'b1; s_data = 8'h5A; m_ready = 1'b0;
        #1;
        check(m_valid === 1'b0 && m_valid1 === 1'b0, "latency: not offered in accepting cycle");
        cycle(1'b1, 8'h5A, 1'b0);
        check(dut_up === 1'b1, "latency: beat accepted");
        check(m_valid === 1'b1 && m_data === 8'h5A, "latency: offered after the accepting edge");
        cycle(1'b0, 8'h00, 1'b1);
        check(dut_dn === 1'b1 && out_beat === 8'h5A, "latency: beat leaves when taken");
        check(m_valid === 1'b0, "latency: empty after drain");

        // ---- Full throughput ----
        for (i = 0; i < 64; i = i + 1) begin
            cycle(1'b1, i[7:0], 1'b1);
            check(dut_up === 1'b1, "throughput: a beat enters on every edge");
            if (i > 0) begin
                check(dut_dn === 1'b1, "throughput: a beat leaves on every edge");
                check(out_beat === (i[7:0] - 8'd1), "throughput: beats leave in order");
            end
        end
        cycle(1'b0, 8'h00, 1'b1);
        check(dut_dn === 1'b1 && out_beat === 8'd63, "throughput: last beat leaves");
        check(count == 0 && m_valid === 1'b0, "throughput: drained");

        // ---- Stall with one beat held, then two ----
        cycle(1'b1, 8'hA1, 1'b0);
        check(dut_up === 1'b1, "stall: first beat accepted");
        cycle(1'b1, 8'hA2, 1'b0);
        check(dut_up === 1'b1, "stall: one beat held, a second is accepted");
        check(s_ready === 1'b0 && s_ready1 === 1'b0, "stall: two beats held, s_ready low");
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 8'hA3, 1'b0);
            check(dut_up === 1'b0, "stall: two held, a third is not accepted");
            check(m_data === 8'hA1, "stall: oldest beat still offered");
        end

        // ---- Ready rises after the stall ----
        k = n_out;
        cycle(1'b1, 8'hA3, 1'b1);
        check(dut_dn === 1'b1 && dut_up === 1'b0, "release: oldest leaves, no beat enters");
        check(out_beat === 8'hA1, "release: first beat out is A1");
        check(s_ready === 1'b1, "release: s_ready rises after a beat leaves");
        cycle(1'b1, 8'hA3, 1'b1);
        check(dut_dn === 1'b1 && dut_up === 1'b1, "release: A2 leaves while A3 enters");
        check(out_beat === 8'hA2, "release: second beat out is A2");
        cycle(1'b0, 8'h00, 1'b1);
        check(dut_dn === 1'b1 && out_beat === 8'hA3, "release: third beat out is A3");
        check((n_out - k) == 3 && count == 0, "release: every beat out exactly once");

        // ---- Random traffic against the model ----
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random(seed);
            if (((i / 300) % 2) == 0) rnd_mr = r[2] | r[3];
            else                      rnd_mr = r[2] & r[3];
            if (((i / 450) % 2) == 0) cycle(r[0] | r[1], r[15:8], rnd_mr);
            else                      cycle(r[0],        r[15:8], rnd_mr);
        end
        k = 0;
        while (count > 0 && k < 8) begin
            cycle(1'b0, 8'h00, 1'b1);
            k = k + 1;
        end
        check(count == 0 && m_valid === 1'b0 && m_valid1 === 1'b0, "random: drained");
        check(n_in == (n_out + n_drop), "random: every accepted beat left once");

        // ---- Reset with beats held ----
        cycle(1'b1, 8'hC1, 1'b0);
        cycle(1'b1, 8'hC2, 1'b0);
        check(count == 2 && m_valid === 1'b1 && s_ready === 1'b0, "reset test: two beats held");
        rst_n = 1'b0;
        cycle(1'b1, 8'hC3, 1'b0);
        check(m_valid === 1'b0 && s_ready === 1'b1, "w8 reset with beats held drops them");
        check(m_valid1 === 1'b0 && s_ready1 === 1'b1, "w1 reset with beats held drops them");
        rst_n = 1'b1;
        cycle(1'b0, 8'h00, 1'b1);
        check(m_valid === 1'b0 && dut_dn === 1'b0, "reset: no stale beat after reset");
        cycle(1'b1, 8'hC4, 1'b1);
        check(dut_up === 1'b1 && dut_dn === 1'b0, "post-reset: new beat accepted");
        cycle(1'b0, 8'h00, 1'b1);
        check(dut_dn === 1'b1 && out_beat === 8'hC4, "post-reset: new beat delivered");
        check(n_in == (n_out + n_drop), "final: accounting of all beats");

        finish_run;
    end

    // Watchdog.
    initial begin
        #2000000;
        failed = failed + 1;
        $error("watchdog timeout");
        finish_run;
    end

endmodule
`default_nettype wire
=== END FILE ===
